		size_t len = iov[i].iov_len;
		long n;

		if (len == 0)
			continue;

		n = minixrs_write(fd, iov[i].iov_base, len);
		if (n < 0)
			return total ? total : n;

		total += n;

		/* A short write ends the call -- writev is allowed to be
		 * short, and continuing would silently reorder the stream. */
		if ((size_t)n < len)
