/* SPDX-License-Identifier: BSD-3-Clause */
/* Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors */
/*
 * minix.rs `hello` -- the first C program to run on minix.rs (slice 5.6).
 *
 * This is Phase 5's milestone A: a C program compiled against the musl fork
 * (external/musl), exec'd out of the boot archive by `init`, with `printf`
 * reaching the serial console through VFS -> TTY. Everything under it shipped
 * in earlier slices -- grants (5.2), the console driver and CDEV band (5.3),
 * the POSIX write path (5.4), and the SysV initial stack that lets musl's crt
 * run unpatched (5.5).
 *
 * Nothing here is minix.rs-specific. That is the entire point: this is ordinary
 * C against ordinary <stdio.h>, and it works because the libc underneath it was
 * ported, not because the program was.
 *
 * Each line is self-checking in the 5.3/5.4 style -- a marker that only appears
 * when the thing it names actually worked, rather than a trace that appears
 * whenever the code was reached.
 */

#include <errno.h>
#include <stdio.h>
#include <unistd.h>

int main(void)
{
	ssize_t n;

	/*
	 * The milestone. stdout is FULLY buffered (the fork's ioctl answers
	 * -ENOTTY, so __stdout_write sets f->lbf = -1), which means this line
	 * does not reach the console here -- it is flushed by exit()'s
	 * __stdio_exit on the way out. So this marker also proves the flush
	 * path, not just the formatting.
	 */
	printf("minix.rs hello: Hello from C!\n");

	/* stderr is unbuffered, so this one goes out immediately -- a different
	 * descriptor and a different buffering mode through the same VFS path. */
	fprintf(stderr, "minix.rs hello: stderr works\n");

	/*
	 * The errno identity check (phase-5 decision D7), at RUNTIME.
	 *
	 * D7 makes minix.rs's POSIX errno magnitudes identical to Linux/musl's,
	 * which is what lets musl's stock bits/errno.h and syscall_ret.c work
	 * unmodified. tools/build-musl.sh proves that at compile time; this
	 * proves the whole chain end to end -- VFS answers EBADF, the driver
	 * relays it, the kernel returns it, syscall_ret.c turns the negative
	 * return into errno, and the value C sees is the one C expects.
	 *
	 * fd 3 is deliberate: it is inside VFS's fd row but not open, so it is
	 * the one descriptor that is well-formed in every respect except being
	 * open. (init's `bad-fd` denial probe uses the same descriptor.)
	 */
	errno = 0;
	n = write(3, "x", 1);
	if (n == -1 && errno == EBADF)
		printf("minix.rs hello: errno ok\n");
	else
		printf("minix.rs hello: errno FAIL n=%d errno=%d\n",
		       (int)n, errno);

	/* Returning from main runs exit(), which flushes stdout and then issues
	 * PM_EXIT. init reaps us and forks the next cycle. */
	return 0;
}

/*
 * minix.rs user-space linker script (aarch64 EL0 `hello` — the slice-5.6 C
 * milestone, linked against the musl fork).
 *
 * Derived from `userland/worker/user.ld`, and the parts they share are load-
 * bearing in exactly the same way: a static ET_EXEC ELF the kernel's minimal
 * loader (`kernel/src/boot_image/elf.rs`) maps segment-by-segment into a fresh
 * per-process AddrSpace, every PT_LOAD page-aligned in vaddr *and* file offset,
 * no dynamic sections or relocations, and the same 0x0010_0000 load base (safe
 * to share, because exec always builds its own per-process TTBR0).
 *
 * The FILEHDR PHDRS idiom on the text segment is MANDATORY, not cosmetic.
 * Without it lld's default aarch64 max-page-size (64 KiB) puts PT_LOAD #0 at
 * file offset 0x10000 and leaves `e_phoff` in an unmapped prefix — so SYS_EXEC
 * has no mapped VA to report as AT_PHDR, and musl's `__init_tls`, which walks
 * the program headers from exactly that pointer, would dereference nothing.
 * For a Rust binary that costs an auxv entry; here it is a fault at startup.
 *
 * What this script has to place that a Rust one does not, all of it arriving
 * from crti.o / crtn.o / libc.a:
 *
 *   .init / .fini              `_init` and `_fini`, which crt1.c hands to
 *                              __libc_start_main. Orphaned, they land outside
 *                              a PT_LOAD and the call jumps into nothing.
 *   .init_array / .fini_array  walked by __libc_start_init and libc_exit_fini.
 *                              The bracketing symbols are weak-hidden in musl,
 *                              so an undefined pair merely skips the walk —
 *                              but a section placed with no symbols would be
 *                              walked with garbage bounds. Define both.
 *   .got / .data.rel.ro        emitted even for a static non-PIE link.
 *
 * Every input section gets an explicit home. An orphan placed past the last
 * PT_LOAD is a SILENT load failure — the loader maps what the phdrs describe
 * and never sees it. Verify with:
 *   llvm-readobj --program-headers --elf-output-style=GNU target/hello/hello
 *
 * There is deliberately no PT_TLS: musl keeps errno in the pthread struct via
 * tpidr_el0 rather than in a __thread variable, so libc.a carries no .tdata or
 * .tbss and __init_tls uses its static builtin_tls. The rules below still catch
 * those sections so a future libc change surfaces as a link-time surprise
 * rather than a runtime one.
 */

OUTPUT_FORMAT(elf64-littleaarch64)
OUTPUT_ARCH(aarch64)
ENTRY(_start)

PHDRS {
    text   PT_LOAD FILEHDR PHDRS FLAGS(5); /* R+X */
    rodata PT_LOAD FLAGS(4); /* R   */
    data   PT_LOAD FLAGS(6); /* RW  */
    note   PT_NOTE FLAGS(4); /* minixrs identity note */
}

SECTIONS {
    . = 0x00100000 + SIZEOF_HEADERS;

    .text : ALIGN(4K) {
        KEEP(*(.text._start))
        *(.text .text.*)
    } :text

    /* crti.o / crtn.o bracket these; _init and _fini live inside them. */
    .init : {
        KEEP(*(.init))
    } :text

    .fini : {
        KEEP(*(.fini))
    } :text

    . = ALIGN(4K);
    /*
     * minixrs identity note (tooling/docs/abi-note.md): first thing in the RO
     * segment, dual-assigned so it lands in the rodata PT_LOAD *and* its own
     * PT_NOTE phdr. KEEP() is mandatory — nothing references the section — and
     * this rule must stay ahead of the /DISCARD/ *(.note.*) rule below (first
     * match wins).
     *
     * For a C binary the note comes from crt1.o, where the fork emits it as a
     * .pushsection global asm, so every C program is branded with no opt-in.
     */
    .note.minixrs.ident : {
        KEEP(*(.note.minixrs.ident))
    } :rodata :note

    .rodata : {
        *(.rodata .rodata.*)
    } :rodata

    . = ALIGN(4K);

    /*
     * Constructor/destructor arrays. PROVIDE_HIDDEN matches what musl declares
     * (weak hidden), and bracketing them here is what keeps the walk bounded.
     */
    .preinit_array : {
        PROVIDE_HIDDEN(__preinit_array_start = .);
        KEEP(*(.preinit_array))
        PROVIDE_HIDDEN(__preinit_array_end = .);
    } :data

    .init_array : {
        PROVIDE_HIDDEN(__init_array_start = .);
        KEEP(*(SORT_BY_INIT_PRIORITY(.init_array.*)))
        KEEP(*(.init_array))
        PROVIDE_HIDDEN(__init_array_end = .);
    } :data

    .fini_array : {
        PROVIDE_HIDDEN(__fini_array_start = .);
        KEEP(*(SORT_BY_INIT_PRIORITY(.fini_array.*)))
        KEEP(*(.fini_array))
        PROVIDE_HIDDEN(__fini_array_end = .);
    } :data

    .data.rel.ro : {
        *(.data.rel.ro .data.rel.ro.*)
    } :data

    .got : {
        *(.got .got.plt)
    } :data

    .data : {
        *(.data .data.*)
    } :data

    /* No PT_TLS is emitted; these rules exist so a libc that grows TLS fails
     * loudly at link time instead of silently mapping it as ordinary data. */
    .tdata : {
        *(.tdata .tdata.*)
    } :data

    .bss : ALIGN(4K) {
        *(.tbss .tbss.*)
        *(.bss .bss.*)
        *(COMMON)
    } :data

    /DISCARD/ : {
        *(.eh_frame)
        *(.eh_frame_hdr)
        *(.note .note.*)
        *(.comment)
        *(.dynsym .dynstr .hash .gnu.hash .dynamic)
        *(.rela .rela.*)
    }
}

